-- Já aplicada no cknb (15/11/2026) via MCP com o carimbo de calendário 20261115125550 (seguranca_acl_tabelas_caminho_estoque).
-- Idempotente: pode ser reexecutada pelo workflow de migrations sem efeito adicional
-- (CREATE OR REPLACE, DROP TRIGGER IF EXISTS, GRANT/REVOKE determinísticos).
-- Restaura o contrato de ACL de tabelas/views do repo (perdido na migração ssvx->cknb).
-- Inclui o caminho de escrita de estoque: authenticated não escreve mais saldo/ledger direto
-- (stock_movements, colunas de saldo de products, etc.) — só pelas commands SECURITY DEFINER.
-- Privilégios por coluna existentes são preservados (REVOKE em tabela também remove os de coluna).
SET LOCAL statement_timeout = '600s';
DROP TABLE IF EXISTS pg_temp._col_acl;
CREATE TEMP TABLE _col_acl AS
SELECT c.oid AS relid, a.attname, (aclexplode(a.attacl)).* FROM pg_attribute a
JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL;
