DO $c$ DECLARE r record; BEGIN
  FOR r IN SELECT relid::regclass AS rel, attname, grantee::regrole AS grantee, privilege_type FROM _col_acl
           WHERE grantee <> 0 AND grantee::regrole::text <> 'postgres' LOOP
    EXECUTE format('GRANT %s (%I) ON TABLE %s TO %s', r.privilege_type, r.attname, r.rel, r.grantee);
  END LOOP;
END $c$;
